'use strict';
const fieldInfo={staminaGain:['체력 레벨당 증가량',1],speedGain:['속도 레벨당 증가율',.001],enduranceGain:['지구력 레벨당 피로 감소율',.0005],efficiencyCap:['주행 효율 최대 감소율',.01],baseDrain:['1m당 기본 체력 소모',.005],boostCost:['가속 기본 체력 비용',1],boostCostGain:['가속 레벨당 추가 비용',.1],boostDuration:['가속 지속 시간 (경기 초)',1],boostGain:['가속 기본 속도 증가율',.01],trainingReward:['800m 훈련 완주 코인',1],finishReward:['800m 공식 완주 코인',1],costScale:['강화 비용 배율',.05],costGrowth:['강화 비용 레벨 증가 배율',.005],opponentLevel:['공식 상대 기준 레벨',1]};
let draft=null,labResults=null;
function buildLab(){draft=E.clone(p.settings);$('game').classList.add('hidden');$('lab').classList.add('open');$('lab').innerHTML=`<div class="lab-heading"><div><span class="eyebrow">BALANCE LAB / SIMULATION</span><h2>성장의 속도를 설계하다.</h2><p>같은 경기 엔진으로 수치를 비교하세요. 시뮬레이션은 실제 코인·레벨·기록에 영향을 주지 않습니다.</p></div><button class="quiet" id="closeLab">← 경기장으로</button></div><div class="lab-grid"><section class="panel"><div class="panel-head"><h2>01 밸런스 조정</h2><button class="quiet" id="resetDraft">기본값</button></div><div class="lab-fields">${Object.entries(fieldInfo).map(([k,[label,step]])=>`<label class="field">${label}<input type="number" id="cfg-${k}" min="${E.LIMITS[k][0]}" max="${E.LIMITS[k][1]}" step="${step}" value="${draft[k]}"><small>${E.LIMITS[k][0]}–${E.LIMITS[k][1]}${['speedGain','enduranceGain','boostGain','efficiencyCap'].includes(k)?' · 비율 0.01 = 1%':''}</small></label>`).join('')}${E.DISTANCES.map(d=>`<label class="field">${d}m 보상 가중치<input type="number" id="weight-${d}" min="0.1" max="20" step="0.1" value="${draft.distanceWeights[d]}"></label>`).join('')}</div><div class="lab-action"><button class="quiet" id="applyConfig">현재 게임에 적용</button><button class="quiet" id="exportConfig">설정 내보내기</button></div><p class="scope-note">적용하면 이후 경기와 강화에 사용합니다. 기존 선수 레벨·코인·완주 횟수는 유지됩니다. 실험 결과를 비교한 뒤 적용하세요.</p></section><div><section class="panel"><div class="panel-head"><h2>02 첫 공식 입상까지</h2><span class="tag">TARGET 50–60 MIN</span></div><p class="lab-note">새 선수 → 훈련 5회 완주 → 800m 공식경기 반복. 일정 페이스, 마지막 구간 자동 가속으로 비교합니다. 게임에서 가속은 수동입니다.</p><div class="lab-fields"><label class="field">강화 구매 전략<select id="policy"><option value="record">기록 우선 · 속도에 먼저 투자</option><option value="balanced">균형 성장 · 6개 능력치 분산</option></select></label><label class="field">비교 선수 수<select id="samples"><option>10</option><option>20</option><option>50</option></select></label><label class="field">경기 재생 배속<select id="simSpeed"><option>1</option><option>2</option><option selected>4</option><option>8</option></select></label><label class="field">경기 사이 조작 시간 (초)<input type="number" id="between" min="0" max="120" value="15"></label></div><div class="lab-action"><button class="primary" id="runBatch">성장 시뮬레이션 실행 →</button><button class="quiet" id="cancelSim" disabled>중지</button></div><div class="lab-output" id="batchOutput" aria-live="polite">최대 150경기까지 비교합니다. 같은 설정은 같은 난수 시드로 재현됩니다. 50–60분은 강제 잠금이 아닌 조정 목표입니다.</div></section><section class="panel spacer"><div class="panel-head"><h2>03 능력치별 테스트 경기</h2></div><div class="lab-levels">${E.KEYS.map(k=>`<label class="field">${E.LABELS[k]}<input id="lv-${k}" type="number" min="1" max="100" step="1" value="${p.levels[k]}"></label>`).join('')}</div><div class="lab-fields"><label class="field">테스트 거리<select id="testDistance">${E.DISTANCES.map(d=>`<option value="${d}">${d}m</option>`).join('')}</select></label><label class="field">주행 전략<select id="testStrategy">${Object.entries(E.STRATEGIES).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label><label class="field">경기장<select id="testMode"><option value="stadium">스타디움</option><option value="training">훈련장</option></select></label><label class="field">가속 사용<select id="testBoost"><option value="yes">후반 자동 사용</option><option value="no">사용하지 않음</option></select></label></div><div class="lab-action"><button class="primary" id="runSingle">테스트 경기 계산</button></div><div class="lab-output" id="singleOutput">체력 부족과 후반 속도 저하를 따로 비교해 보세요. 테스트는 즉시 결과를 계산합니다.</div></section></div></div>`;
$('closeLab').onclick=()=>{stopWorker();$('game').classList.remove('hidden');$('lab').classList.remove('open');update();};$('resetDraft').onclick=()=>{for(const k in fieldInfo)$('cfg-'+k).value=E.DEFAULT[k];for(const d of E.DISTANCES)$('weight-'+d).value=E.DEFAULT.distanceWeights[d];};$('applyConfig').onclick=()=>{const c=readConfig();if(!c)return;p.settings=c;save();toast('새 밸런스를 적용했습니다. 다음 경기부터 사용합니다.');};$('exportConfig').onclick=()=>{const c=readConfig();if(c)download('runners-high-balance.json',c);};$('runBatch').onclick=runBatch;$('cancelSim').onclick=()=>{stopWorker();$('batchOutput').textContent='중지했습니다. 실제 선수 데이터는 변경되지 않았습니다.';};$('runSingle').onclick=runSingle;
}
function readConfig(){const c={distanceWeights:{}};for(const k in fieldInfo){const el=$('cfg-'+k);if(!el.value||!el.checkValidity()){el.reportValidity();return null;}c[k]=+el.value;}for(const d of E.DISTANCES){const el=$('weight-'+d);if(!el.value||!el.checkValidity()){el.reportValidity();return null;}c.distanceWeights[d]=+el.value;}return E.config(c);}
function stopWorker(){if(worker){worker.terminate();worker=null;}if($('runBatch')){$('runBatch').disabled=false;$('runSingle').disabled=false;$('cancelSim').disabled=true;}}
function beginWorker(){stopWorker();worker=new Worker('worker.js');$('runBatch').disabled=true;$('runSingle').disabled=true;$('cancelSim').disabled=false;worker.onerror=()=>{toast('시뮬레이션 실행 오류가 발생했습니다. 다시 실행해 주세요.');stopWorker();};return worker;}
function runBatch(){const c=readConfig();if(!c)return;if(!$('between').value||!$('between').checkValidity()){$('between').reportValidity();return;}const options={policy:$('policy').value,playback:+$('simSpeed').value,between:+$('between').value,maxRaces:150},count=+$('samples').value;const w=beginWorker();$('batchOutput').textContent='새 선수의 성장을 계산하는 중…';w.onmessage=({data})=>{if(data.type==='progress'){$('batchOutput').textContent=`계산 중 ${data.done} / ${data.total}명`;return;}if(data.type==='error'){toast(data.message);stopWorker();return;}if(data.type==='complete'){labResults={config:c,options,results:data.results};showBatch(data.results,options);stopWorker();}};w.postMessage({type:'batch',config:c,options,count});}
function showBatch(results,options){const ok=results.filter(r=>r.success).sort((a,b)=>a.minutes-b.minutes);const median=ok.length?(ok[Math.floor((ok.length-1)/2)].minutes+ok[Math.ceil((ok.length-1)/2)].minutes)/2:null;const example=ok[Math.floor(ok.length/2)]||results[0];$('batchOutput').innerHTML=`<h3>${median===null?'입상 미달성':median.toFixed(1)+'분 · 성공 선수 중앙값'}</h3><p>${options.playback}배속 · 경기 사이 ${options.between}초 · 성공 ${ok.length}/${results.length}명. ${ok.length?`성공 범위 ${ok[0].minutes.toFixed(1)}–${ok.at(-1).minutes.toFixed(1)}분.`:''} 미달성 선수는 150경기에서 종료하며 중앙값에서 제외합니다.</p><p>${median===null?'강화 비용이나 공식 상대 수준을 낮춰 보세요.':median<50?'목표보다 빠릅니다. 강화 비용이나 상대 수준을 높여 보세요.':median>60?'목표보다 느립니다. 강화 비용이나 상대 수준을 낮춰 보세요.':'중앙값이 목표 50–60분 안에 있습니다. 범위도 함께 확인하세요.'}</p><div class="table-scroll"><table><thead><tr><th>선수</th><th>첫 입상</th><th>경기 수</th><th>상태</th></tr></thead><tbody>${results.map((r,i)=>`<tr><td>${i+1}</td><td>${r.minutes.toFixed(1)}분${r.success?'':' 이상'}</td><td>${r.races}</td><td>${r.success?'입상':'미달성'}</td></tr>`).join('')}</tbody></table></div><details><summary>대표 선수의 경기·강화 기록</summary><div class="table-scroll"><table><thead><tr><th>경기</th><th>기록 / 순위</th><th>강화</th><th>코인 잔액</th></tr></thead><tbody>${example.logs.map(l=>`<tr><td>${l.race} ${l.mode==='training'?'훈련':'공식'}</td><td>${fmt(l.time)} / ${l.rank||'DNF'}</td><td>${l.upgrades.map(u=>`${E.LABELS[u.stat]} ${u.level}Lv (−${u.cost})`).join(', ')||'저축'}</td><td>${l.coins}</td></tr>`).join('')}</tbody></table></div></details><button class="quiet spacer" id="exportResults">전체 결과 JSON 저장</button>`;$('exportResults').onclick=()=>download('runners-high-simulation.json',labResults);}
function runSingle(){const c=readConfig();if(!c)return;const l={};for(const k of E.KEYS){const el=$('lv-'+k);if(!el.value||!el.checkValidity()){el.reportValidity();return;}l[k]=+el.value;}const options={levels:l,distance:+$('testDistance').value,strategy:$('testStrategy').value,mode:$('testMode').value,settings:c,seed:42};const auto=$('testBoost').value==='yes';const w=beginWorker();$('singleOutput').textContent='계산 중…';w.onmessage=({data})=>{if(data.type==='error'){toast(data.message);stopWorker();return;}if(data.type==='single'){const a=data.racers.find(x=>x.id===0);$('singleOutput').innerHTML=`<h3>${fmt(a.finish)} · ${data.reward.rank?data.reward.rank+'위':'완주 실패'}</h3><p>${options.distance}m / ${E.STRATEGIES[options.strategy].name} / ${auto?'후반 가속':'가속 없음'}</p><div class="metric-row"><div><strong>${a.distance.toFixed(0)}m</strong><small>도달 거리</small></div><div><strong>${a.stamina.toFixed(1)}</strong><small>남은 체력 / ${a.capacity}</small></div><div><strong>${(a.fatigue*100).toFixed(1)}%</strong><small>마지막 피로 속도 감소</small></div></div><p>가속 ${a.boosted}회 사용 · 예상 보상 ${data.reward.total} C (실제 지급하지 않음)</p>`;stopWorker();}};w.postMessage({type:'single',options,auto});}
if(document.modelContext?.registerTool){const schema={type:'object',properties:{},additionalProperties:false};for(const tool of [{name:'get_runner_state',description:'현재 선수 레벨, 재화, 훈련 완주 수와 경기 진행을 읽습니다.',inputSchema:schema,annotations:{readOnlyHint:true},execute:()=>({coins:p.coins,levels:E.clone(p.levels),training:p.training,mode,distance,race:race?{time:race.time,done:race.done,paused}:null})},{name:'open_balance_lab',description:'경기가 진행 중이 아닐 때 밸런스 실험실 화면을 엽니다. 선수 데이터는 변경하지 않습니다.',inputSchema:schema,annotations:{readOnlyHint:false},execute:input=>{if(Object.keys(input||{}).length)throw Error('No input properties allowed');if(race&&!race.done)throw Error('Finish the active race first');buildLab();return {opened:true};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}

